/**
 * Catalog Companions Registry — 3 premium AI companion iPhone screens per hero.
 *
 * Each hero PNG in `catalog-mockup-registry.ts` has a matching triple of
 * companion screens (menu, detail, booking) generated by Gemini using the
 * hero as visual reference. This guarantees identical palette / typography /
 * lighting across the 4-phone lineup shown on `/portfolio`.
 */

import type { IndustryId } from "@/config/industry-config";

// Eagerly import every companion PNG. Vite gives us a stable module URL.
const companionFiles = import.meta.glob(
  "@/assets/mockups/catalog/companions/*.png",
  { eager: true, import: "default" },
) as Record<string, string>;

// Group companions by their hero stem (portion before "--<index>-<slug>.png")
const byStem = new Map<string, string[]>();
for (const [path, url] of Object.entries(companionFiles)) {
  const filename = path.split("/").pop() ?? "";
  const m = filename.match(/^(.+?)--(\d+)-.+\.png$/);
  if (!m) continue;
  const stem = m[1];
  const idx = parseInt(m[2], 10);
  const bucket = byStem.get(stem) ?? [];
  bucket[idx - 2] = url; // indices are 2,3,4 → array slot 0,1,2
  byStem.set(stem, bucket);
}

