function slug(v: string): string {
  return v.toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

/**
 * Returns the 3 companion screen URLs (menu, detail, booking) for a given
 * (sector, brand, style) triple, or null when no premium companions exist.
 */
export function catalogCompanionUrls(
  sector: IndustryId,
  brand: string,
  style: string,
): string[] | null {
  const key = `${sector}::${slug(brand)}::${slug(style)}`;
  const stem = HERO_STEM_BY_KEY[key];
  if (!stem) return null;
  const urls = byStem.get(stem);
  if (!urls || urls.length < 3 || urls.some((u) => !u)) return null;
  return urls.slice(0, 3);
}
